import { defineStore } from 'pinia';

export type ActiveScreen = 'field-validation' | 'medi-order' | 'approval-v2' | 'approval-v3';

export const useActiveScreenStore = defineStore('active_screen', {
  state: () => ({ screen: null as ActiveScreen | null }),
  actions: {
    setScreen(screen: ActiveScreen) {
      this.screen = screen;
    },
    clear() {
      this.screen = null;
    },
  },
});
